using System.Security.Claims; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.Api.Data; using RaceDay.Api.DTOs; using RaceDay.Api.Models;
namespace RaceDay.Api.Controllers;
[ApiController,Route("api/enrolments")]
public class EnrolmentsController(RaceDayDbContext db):ControllerBase {
 int UserId=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 [Authorize(Roles=Roles.Participant),HttpPost] public async Task<IActionResult> Enrol(EnrolmentRequest r){var e=await db.Events.FindAsync(r.EventId);var c=await db.Categories.FindAsync(r.CategoryId);if(e==null||c==null||c.EventId!=r.EventId)return BadRequest(new{message="Event or category does not exist or category belongs to another event."});if(e.EventDate<DateTime.UtcNow)return Conflict(new{message="Cannot enrol in an event that has already taken place."});if(await db.Enrolments.AnyAsync(x=>x.ParticipantId==UserId&&x.EventId==r.EventId))return Conflict(new{message="You have already enrolled in this event."});var en=new Enrolment{ParticipantId=UserId,EventId=r.EventId,CategoryId=r.CategoryId};db.Enrolments.Add(en);await db.SaveChangesAsync();return Created($"/api/enrolments/{en.EnrolmentId}",new{en.EnrolmentId,en.EventId,en.CategoryId,en.Status,en.EnrolledAt});}
 [Authorize(Roles=Roles.Participant),HttpGet("mine")] public async Task<IActionResult> Mine()=>Ok(await db.Enrolments.Where(x=>x.ParticipantId==UserId).Include(x=>x.Event).Include(x=>x.Category).Include(x=>x.Result).Select(x=>new{x.EnrolmentId,x.Status,Event=x.Event!.Name,x.Event.EventDate,Category=x.Category!.Name,Result=x.Result==null?null:new{x.Result.FinishTime,x.Result.FinishingPosition}}).ToListAsync());
 [Authorize(Roles=Roles.Organiser),HttpGet("event/{eventId:int}")] public async Task<IActionResult> ForEvent(int eventId){var e=await db.Events.FindAsync(eventId);if(e==null)return NotFound();if(e.OrganiserId!=UserId)return Forbid();return Ok(await db.Enrolments.Where(x=>x.EventId==eventId).Include(x=>x.Participant).Include(x=>x.Category).Select(x=>new{x.EnrolmentId,ParticipantId=x.ParticipantId,Participant=x.Participant!.FullName,Email=x.Participant.Email,Category=x.Category!.Name,x.Status,x.EnrolledAt}).ToListAsync());}
 [Authorize(Roles=Roles.Participant),HttpDelete("{id:int}")] public async Task<IActionResult> Withdraw(int id){var en=await db.Enrolments.FindAsync(id);if(en==null)return NotFound();if(en.ParticipantId!=UserId)return Forbid();db.Enrolments.Remove(en);await db.SaveChangesAsync();return NoContent();}
}
